define({"topics":[{"title":"Electrical Safety","shortdesc":"<p class=\"shortdesc\">You must follow all recommended safety procedures when servicing and working near energy sources.<\/p>","href":"r_ElectricalSafety_63.html","attributes":{"data-id":"id_2001693"},"menu":{"hasChildren":false},"tocID":"id_2001693-d46e218130","topics":[]},{"title":"Preparing the workstation for a computer replacement","shortdesc":"<p class=\"shortdesc\">Prepare the workstation so all data is saved prior to shutting down and replacing the host computer in the Global Operator Cabinet (GOC).<\/p>","href":"t_PreparingTheWorkstationForAComputerReplacement.html","attributes":{"data-id":"id_2007196"},"menu":{"hasChildren":false},"tocID":"id_2007196-d46e218234","topics":[]},{"title":"Shutting down the host computer","shortdesc":"<p class=\"shortdesc\">Shutting down the host computer shuts down the system safely and turns off the power to the host computer.<\/p>","href":"t_ShuttingDownHostComputer_65.html","attributes":{"data-id":"id_2001469"},"menu":{"hasChildren":false},"tocID":"id_2001469-d46e218338","topics":[]},{"title":"Applying LOTO - Global Operator Cabinet (GOC) and operator workspace","shortdesc":"<p class=\"shortdesc\">Apply LOTO before servicing the GOC or items in the operator workspace. Applying LOTO makes sure the environment is safe when working on these items.<\/p>","href":"t_Applying-LOTO-GOCandOWLOTO-Premier_7.html","attributes":{"data-id":"id_2001924"},"menu":{"hasChildren":false},"tocID":"id_2001924-d46e218442","topics":[]},{"title":"Removing the host computer <span class=\"ph\">- Dell T5810<\/span>","shortdesc":"<p class=\"shortdesc\">Remove the host computer from the Global Operator Cabinet (GOC) when upgrading the system.<\/p>","href":"t_RemovingTheHostComputer-DellT5810_3.html","attributes":{"data-id":"id_2001773"},"menu":{"hasChildren":false},"tocID":"id_2001773-d46e218546","topics":[]},{"title":"Transferring the USB expansion panel to the new host computer<span class=\"ph\"> - Dell T5810<\/span>","shortdesc":"<p class=\"shortdesc\">Remove the USB expansion panel from the old host computer and install it in the new host computer.<\/p>","href":"t_TransferringTheUSBExpansionPanelToTheNewHostComputer.html","attributes":{"data-id":"id_2007295"},"menu":{"hasChildren":false},"tocID":"id_2007295-d46e218652","topics":[]},{"title":"Installing the host computer <span class=\"ph\">- Dell T5810<\/span>","shortdesc":"<p class=\"shortdesc\">Install the host computer in the Global Operator Cabinet (GOC) after it has been serviced or replaced.<\/p>","href":"t_InstallingTheHostComputer-DellT5810_3.html","attributes":{"data-id":"id_2001778"},"menu":{"hasChildren":false},"tocID":"id_2001778-d46e218758","topics":[]},{"title":"Removing LOTO - Global Operator Cabinet (GOC) and operator workspace","shortdesc":"<p class=\"shortdesc\">Remove LOTO from the GOC and operator workspace before restoring power to these items.<\/p>","href":"t_Removing-LOTO-GOCandOW-Premier_7.html","attributes":{"data-id":"id_2001925"},"menu":{"hasChildren":false},"tocID":"id_2001925-d46e218864","topics":[]},{"title":"Starting up the host computer","shortdesc":"<p class=\"shortdesc\">How to start the host computer.<\/p>","href":"t_StartingUpTheHostComputer_64.html","attributes":{"data-id":"id_2001468"},"menu":{"hasChildren":false},"tocID":"id_2001468-d46e218968","topics":[]},{"title":"Finalizing computer or drive replacement","shortdesc":"<p class=\"shortdesc\">Follow this procedure to finalize a computer or hard drive replacement.<\/p>","href":"t_FinalizingComputerOrDriveReplacement.html","attributes":{"data-id":"id_2001779"},"menu":{"hasChildren":false},"tocID":"id_2001779-d46e219072","topics":[]}]});